import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFile,writeFile} from 'node:fs/promises';
import {join} from 'node:path';
import {fixture} from './helpers.js';
async function filled(request,productId='mug-classic',quantity=1){const cart=(await request('/api/carts','POST')).body;await request('/api/carts/'+cart.id+'/items','POST',{productId,quantity});return cart.id;}
test('checkout persists snapshot order, empties cart and reduces stock',async t=>{
 const {request,dir}=await fixture(t);const id=await filled(request);
 await request('/api/carts/'+id+'/discount','POST',{code:'WELCOME10'});
 const r=await request('/api/checkout','POST',{cartId:id,email:'a@b'});assert.equal(r.status,201);
 assert.equal(r.body.items[0].name,'Amber Mug');assert.equal(r.body.items[0].priceCents,1250);assert.equal(r.body.totalCents,1215);
 assert.deepEqual((await request('/api/orders/'+r.body.id)).body,r.body);
 assert.equal((await request('/api/products/mug-classic')).body.stock,19);
 assert.equal((await request('/api/carts/'+id)).body.items.length,0);
 const orders=JSON.parse(await readFile(join(dir,'orders.json'),'utf8'));assert.equal(orders.length,1);assert.equal(orders[0].id,r.body.id);
 assert.equal((await request('/api/orders/missing')).status,404);
});
test('empty and invalid checkout responses',async t=>{
 const {request}=await fixture(t);const id=(await request('/api/carts','POST')).body.id;
 assert.equal((await request('/api/checkout','POST',{cartId:id,email:'no-at'})).status,400);
 assert.equal((await request('/api/checkout','POST',{cartId:id,email:'a@b'})).body.error.code,'EMPTY_CART');
 assert.equal((await request('/api/checkout','POST',{cartId:'missing',email:'a@b'})).status,404);
});
test('insufficient stock names all short products and changes none',async t=>{
 const {request,dir}=await fixture(t);const id=await filled(request,'mug-classic',2);
 await request('/api/carts/'+id+'/items','POST',{productId:'tote-canvas',quantity:1});
 await request('/api/carts/'+id+'/items','POST',{productId:'product-4',quantity:1});
 const products=JSON.parse(await readFile(join(dir,'products.json'),'utf8'));
 products.find(p=>p.id==='mug-classic').stock=0;products.find(p=>p.id==='tote-canvas').stock=0;
 await writeFile(join(dir,'products.json'),JSON.stringify(products));
 const r=await request('/api/checkout','POST',{cartId:id,email:'a@b'});assert.equal(r.status,409);assert.match(r.body.error.message,/Amber Mug/);assert.match(r.body.error.message,/Canvas Tote/);
 assert.equal((await request('/api/products/product-4')).body.stock,20);assert.equal((await request('/api/carts/'+id)).body.items.length,3);
 assert.deepEqual(JSON.parse(await readFile(join(dir,'products.json'),'utf8')),products);
});
test('two simultaneous checkouts for final unit create exactly one order',async t=>{
 const {request,dir}=await fixture(t);const a=await filled(request,'tote-canvas');const b=await filled(request,'tote-canvas');
 const results=await Promise.all([a,b].map(cartId=>request('/api/checkout','POST',{cartId,email:'race@example.com'})));
 assert.deepEqual(results.map(r=>r.status).sort(),[201,409]);assert.equal((await request('/api/products/tote-canvas')).body.stock,0);
 assert.equal(JSON.parse(await readFile(join(dir,'orders.json'),'utf8')).length,1);
});
test('checkout rechecks minimum and active discounts before writes',async t=>{
 const {request,dir}=await fixture(t);const id=await filled(request,'mug-classic',2);
 await request('/api/carts/'+id+'/discount','POST',{code:'SAVE500'});
 await request('/api/carts/'+id+'/items/mug-classic','PATCH',{quantity:1});
 assert.equal((await request('/api/checkout','POST',{cartId:id,email:'a@b'})).status,422);
 await request('/api/carts/'+id+'/discount','POST',{code:'WELCOME10'});
 const discounts=JSON.parse(await readFile(join(dir,'discounts.json'),'utf8'));discounts.find(d=>d.code==='WELCOME10').active=false;await writeFile(join(dir,'discounts.json'),JSON.stringify(discounts));
 assert.equal((await request('/api/checkout','POST',{cartId:id,email:'a@b'})).body.error.code,'INVALID_DISCOUNT');
 assert.equal((await request('/api/products/mug-classic')).body.stock,20);
});

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {fixture} from './helpers.js';
test('percentage, fixed, minimum, cap, invalid and removal discounts',async t=>{
 const {request}=await fixture(t);const id=(await request('/api/carts','POST')).body.id;
 await request('/api/carts/'+id+'/items','POST',{productId:'mug-classic',quantity:1});
 const percent=await request('/api/carts/'+id+'/discount','POST',{code:'WELCOME10'});
 assert.equal(percent.body.discountCents,125);assert.equal(percent.body.taxCents,90);assert.equal(percent.body.totalCents,1215);
 for(const code of ['SAVE500','INACTIVE','MISSING']){const r=await request('/api/carts/'+id+'/discount','POST',{code});assert.equal(r.status,422);assert.equal(r.body.error.code,'INVALID_DISCOUNT');}
 assert.equal((await request('/api/carts/'+id+'/discount','POST',{})).status,400);
 await request('/api/carts/'+id+'/items','POST',{productId:'mug-classic',quantity:1});
 const fixed=await request('/api/carts/'+id+'/discount','POST',{code:'SAVE500'});assert.equal(fixed.body.discountCents,500);assert.equal(fixed.body.totalCents,2160);
 const capped=await request('/api/carts/'+id+'/discount','POST',{code:'CAP'});assert.equal(capped.body.discountCents,2500);assert.equal(capped.body.totalCents,0);
 const cleared=await request('/api/carts/'+id+'/discount','DELETE');assert.equal(cleared.body.discountCode,null);assert.equal(cleared.body.discountCents,0);
});
